/** The markup for a glyph, or undefined when the set does not have it. */
export function iconBody(name) {
  return Object.prototype.hasOwnProperty.call(ICONS, name) ? ICONS[name] : undefined;
}

/** Is this a glyph the set carries? */
export function hasIcon(name) {
  return Object.prototype.hasOwnProperty.call(ICONS, name);
}

/** Every glyph name in the set, alphabetically. */
export function iconNames() {
  return Object.keys(ICONS);
}
